NOTE_NAMES = ("C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B")


def freq_to_note(freq):
    """
    Convert a frequency in Hz to the nearest musical note string (e.g. 440.0 -> 'A4').
    Returns None if freq <= 0.
    """
    if not freq or freq <= 20.0:
        return None
    midi = int(round(69 + 12 * math.log(freq / 440.0) / math.log(2.0)))
    if midi < 0 or midi > 127:
        return None
    octave = (midi // 12) - 1
    name = NOTE_NAMES[midi % 12]
    return "{}{}".format(name, octave)


def _next_power_of_2(n):
    p = 1
    while p < n:
        p <<= 1
    return p


def fft_magnitudes(pcm_samples):
    """
    Compute the single-sided FFT magnitude spectrum of a 16-bit PCM array/list.
    Uses an in-place Cooley-Tukey Radix-2 FFT with a Hann window and DC offset removal.
    Returns a list of magnitudes of length N // 2.
    """
    n_in = len(pcm_samples)
    if n_in < 2:
        return [0.0]

    # Use largest power of 2 <= len(pcm_samples), capped at 512 for fast MicroPython execution
    n = 1
    while (n << 1) <= n_in and (n << 1) <= 512:
        n <<= 1

    # Remove DC offset
    mean = sum(pcm_samples[:n]) / float(n)

    real = [0.0] * n
    imag = [0.0] * n
    two_pi = 2.0 * math.pi
    denom = float(n - 1) if n > 1 else 1.0

    for i in range(n):
        # Hann window
        w = 0.5 * (1.0 - math.cos(two_pi * i / denom))
        real[i] = (pcm_samples[i] - mean) * w

    # Bit-reversal permutation
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            real[i], real[j] = real[j], real[i]

    # Cooley-Tukey butterflies
    length = 2
    while length <= n:
        half = length >> 1
        angle = -two_pi / float(length)
        w_m_r = math.cos(angle)
        w_m_i = math.sin(angle)
        for i in range(0, n, length):
            w_r = 1.0
            w_i = 0.0
            for k in range(half):
                idx1 = i + k
                idx2 = idx1 + half
                t_r = w_r * real[idx2] - w_i * imag[idx2]
                t_i = w_r * imag[idx2] + w_i * real[idx2]
                u_r = real[idx1]
                u_i = imag[idx1]
                real[idx1] = u_r + t_r
                imag[idx1] = u_i + t_i
                real[idx2] = u_r - t_r
                imag[idx2] = u_i - t_i
                nw_r = w_r * w_m_r - w_i * w_m_i
                w_i = w_r * w_m_i + w_i * w_m_r
                w_r = nw_r
        length <<= 1

    half_n = n >> 1
    scale = 2.0 / float(n)
    mags = [0.0] * half_n
    for i in range(1, half_n):
        mags[i] = math.sqrt(real[i] * real[i] + imag[i] * imag[i]) * scale
    return mags


def spectrum(pcm_samples, bins=16, normalize=True, max_mag=8000.0):
    """
    Compute a grouped frequency spectrum (e.g. for an OLED audio visualizer).

    :param pcm_samples: Array or list of 16-bit signed PCM samples.
    :param bins: Number of frequency bands to return (default: 16).
    :param normalize: If True, scales each band to 0.0..1.0.
    :param max_mag: Reference peak magnitude used when normalize=True.
    :return: List of float values of length ``bins``.
    """
    mags = fft_magnitudes(pcm_samples)
    n_mags = len(mags)
    if bins <= 0:
        return []
    if n_mags <= 1:
        return [0.0] * bins

    result = [0.0] * bins
    # Skip DC bin (index 0)
    usable = n_mags - 1
    for b in range(bins):
        start = 1 + (b * usable) // bins
        end = 1 + ((b + 1) * usable) // bins
        if end <= start:
            end = start + 1
        slice_mags = mags[start:min(end, n_mags)]
        val = (sum(slice_mags) / len(slice_mags)) if slice_mags else 0.0
        if normalize:
            val = clamp(val / float(max_mag), 0.0, 1.0)
        result[b] = round(val, 4)
    return result


def _hz_to_mel(hz):
    return 2595.0 * math.log10(1.0 + hz / 700.0)


def _mel_to_hz(mel):
    return 700.0 * (10.0 ** (mel / 2595.0) - 1.0)


def mfcc(pcm_samples, sample_rate=16000, num_cepstra=13, num_filters=26):
    """
    Compute Mel-Frequency Cepstral Coefficients (MFCC) from a PCM audio buffer.
    Designed for TinyML / Edge Impulse keyword spotting and sound classification on ESP32-S3.

    :param pcm_samples: Array or list of 16-bit signed PCM samples.
    :param sample_rate: Sampling rate in Hz (default: 16000).
    :param num_cepstra: Number of cepstral coefficients to return (default: 13).
    :param num_filters: Number of Mel triangular filters (default: 26).
    :return: List of ``num_cepstra`` float MFCC features.
    """
    if len(pcm_samples) < 4:
        return [0.0] * num_cepstra

    # 1. Pre-emphasis filter (alpha = 0.97)
    n_in = min(len(pcm_samples), 512)
    emphasized = [float(pcm_samples[0])] * n_in
    for i in range(1, n_in):
        emphasized[i] = float(pcm_samples[i]) - 0.97 * float(pcm_samples[i - 1])

    # 2. Power spectrum via FFT
    mags = fft_magnitudes(emphasized)
    n_fft = len(mags) * 2
    power_spec = [(m * m) / float(n_fft) for m in mags]

    # 3. Mel filterbank
    low_mel = _hz_to_mel(20.0)
    high_mel = _hz_to_mel(sample_rate / 2.0)
    mel_points = [
        low_mel + i * (high_mel - low_mel) / float(num_filters + 1)
        for i in range(num_filters + 2)
    ]
    hz_points = [_mel_to_hz(m) for m in mel_points]
    bin_points = [int((n_fft + 1) * h / float(sample_rate)) for h in hz_points]

    filter_energies = [1e-10] * num_filters
    n_bins = len(power_spec)
    for m in range(1, num_filters + 1):
        f_m_minus = bin_points[m - 1]
        f_m = bin_points[m]
        f_m_plus = bin_points[m + 1]
        if f_m == f_m_minus:
            f_m += 1
        if f_m_plus == f_m:
            f_m_plus += 1

        energy = 0.0
        for k in range(max(0, f_m_minus), min(n_bins, f_m)):
            weight = (k - f_m_minus) / float(f_m - f_m_minus)
            energy += power_spec[k] * weight
        for k in range(max(0, f_m), min(n_bins, f_m_plus)):
            weight = (f_m_plus - k) / float(f_m_plus - f_m)
            energy += power_spec[k] * weight

        filter_energies[m - 1] = math.log(max(energy, 1e-10))

    # 4. Discrete Cosine Transform (DCT-II)
    cepstra = [0.0] * num_cepstra
    pi_over_n = math.pi / float(num_filters)
    for c in range(num_cepstra):
        total = 0.0
        for m in range(num_filters):
            total += filter_energies[m] * math.cos(pi_over_n * (m + 0.5) * c)
        cepstra[c] = round(total, 4)

    return cepstra


def build_wav_header(sample_rate, bits_per_sample, channels, num_samples):
    """Build a standard 44-byte RIFF/WAVE header for PCM audio data."""
    byte_rate = sample_rate * channels * (bits_per_sample // 8)
    block_align = channels * (bits_per_sample // 8)
    data_size = num_samples * block_align
    chunk_size = 36 + data_size
    return struct.pack(
        "<4sI4s4sIHHIIHH4sI",
        b"RIFF",
        chunk_size,
        b"WAVE",
        b"fmt ",
        16,                 # PCM chunk size
        1,                  # AudioFormat = 1 (PCM)
        channels,
        sample_rate,
        byte_rate,
        block_align,
        bits_per_sample,
        b"data",
        data_size,
    )


class I2SMic(PinsMixin):
    """
    I2S Digital Microphone controller (INMP441, MSM261S4030H0, SPH0645, etc.).

    Provides picozero-style properties (``level``, ``decibels``, ``peak_freq``, ``note``),
    DSP helpers (``spectrum()``, ``mfcc()``), WAV recording (``record()``, ``save_wav()``),
    and event callbacks (``when_loud``, ``when_quiet``, ``when_clap``).

    Quick start::

        from espzero import I2SMic, esp_led

        mic = I2SMic()  # Uses board profile's default i2s_sck, i2s_ws, i2s_sd pins
        print(mic.level, mic.peak_freq, mic.note)

        mic.when_clap = lambda: esp_led.toggle()
    """

    def __init__(self, sck="i2s_sck", ws="i2s_ws", sd="i2s_sd",
                 i2s_id=0, sample_rate=16000, bits=16,
                 frame_samples=256, threshold=0.25, clap_threshold=0.5,
                 shift=0, ibuf=8192):
        if _hal.I2S is None:
            raise RuntimeError("[espzero] machine.I2S is not available on this board.")

        p = _hal.get_profile()
        sck_gpio = self._resolve_or_fallback(p, sck, 41 if p.CHIP == "esp32s3" else 14)
        ws_gpio  = self._resolve_or_fallback(p, ws,  42 if p.CHIP == "esp32s3" else 15)
        sd_gpio  = self._resolve_or_fallback(p, sd,  2  if p.CHIP == "esp32s3" else 32)

        self._pin_nums = (sck_gpio, ws_gpio, sd_gpio)
        self._i2s_id = i2s_id
        self._sample_rate = int(sample_rate)
        self._bits = int(bits)
        self._frame_samples = int(frame_samples)
        self._threshold = float(threshold)
        self._clap_threshold = float(clap_threshold)
        self._shift = int(shift)

        self._i2s = _hal.I2S(
            i2s_id,
            sck=Pin(sck_gpio),
            ws=Pin(ws_gpio),
            sd=Pin(sd_gpio),
            mode=_hal.I2S.RX,
            bits=self._bits,
            format=_hal.I2S.MONO,
            rate=self._sample_rate,
            ibuf=ibuf,
        )

        self._raw_bytes = bytearray(self._frame_samples * 2)
        self._last_samples = array("h", [0] * self._frame_samples)

        # Event detection state
        self._when_loud = None
        self._when_quiet = None
        self._when_clap = None
        self._is_loud_state = False
        self._last_clap_ms = 0
        self._spike_start_ms = None
        self._poll_timer = _SoftwareTimer()
        self._polling = False

    @staticmethod
    def _resolve_or_fallback(profile, pin, default_gpio):
        if isinstance(pin, str):
            if pin in profile.PIN_ALIASES:
                return profile.PIN_ALIASES[pin]
            return default_gpio
        return int(pin)

    @property
    def sample_rate(self):
        return self._sample_rate

    @property
    def threshold(self):
        return self._threshold

    @threshold.setter
    def threshold(self, val):
        self._threshold = clamp(float(val), 0.0, 1.0)

    @property
    def clap_threshold(self):
        return self._clap_threshold

    @clap_threshold.setter
    def clap_threshold(self, val):
        self._clap_threshold = clamp(float(val), 0.0, 1.0)

    def read_pcm(self, samples=None):
        """
        Read ``samples`` 16-bit signed PCM audio values from the I2S microphone.
        Returns an ``array('h')`` of DC-centered 16-bit samples.
        """
        n = int(samples) if samples is not None else self._frame_samples
        if n == self._frame_samples:
            buf = self._raw_bytes
        else:
            buf = bytearray(n * 2)

        self._i2s.readinto(buf)
        pcm = array("h", [0] * n)
        shift = self._shift
        total = 0
        for i in range(n):
            val = struct.unpack_from("<h", buf, i * 2)[0]
            if shift:
                val = clamp(val << shift, -32768, 32767)
            pcm[i] = val
            total += val

        # Remove static DC bias common on MEMS I2S microphones (e.g. INMP441)
        dc = total // n if n > 0 else 0
        if dc != 0:
            for i in range(n):
                pcm[i] = clamp(pcm[i] - dc, -32768, 32767)

        self._last_samples = pcm
        _hal.record_event("i2s_mic", self._pin_nums[0], "read_pcm", n)
        return pcm

    def _compute_rms(self, pcm=None):
        if pcm is None:
            pcm = self.read_pcm()
        n = len(pcm)
        if n == 0:
            return 0.0
        sum_sq = 0.0
        for s in pcm:
            sum_sq += float(s) * float(s)
        return math.sqrt(sum_sq / float(n))

    @property
    def rms(self):
        """Return the raw 16-bit Root-Mean-Square amplitude (0 .. 32768)."""
        return round(self._compute_rms(), 1)

    @property
    def level(self):
        """
        Return the normalized sound pressure level between 0.0 (silence) and 1.0 (loud).
        Scaled so normal speech/music maps comfortably across 0.1–0.9.
        """
        rms_val = self._compute_rms()
        # Full-scale 16-bit sine wave RMS is ~23170; typical MEMS mic speech is 1000..12000
        return round(clamp(rms_val / 16384.0, 0.0, 1.0), 4)

    value = level

    @property
    def decibels(self):
        """
        Return an estimated sound level in dB SPL (approx. 30 dB silence to 100 dB loud).
        """
        rms_val = max(self._compute_rms(), 1.0)
        db_fs = 20.0 * math.log10(rms_val / 32768.0)
        return round(clamp(94.0 + db_fs, 30.0, 110.0), 1)

    @property
    def is_active(self):
        """True when the current sound level exceeds ``threshold``."""
        return self.level >= self._threshold

    is_loud = is_active

    @property
    def peak_freq(self):
        """
        Return the dominant frequency in Hz from the microphone using FFT with
        parabolic peak interpolation. Useful for whistle detection and instrument tuners.
        """
        pcm = self.read_pcm()
        mags = fft_magnitudes(pcm)
        n_fft = len(mags) * 2
        if len(mags) <= 2:
            return 0.0

        peak_idx = 1
        peak_val = mags[1]
        for i in range(2, len(mags)):
            if mags[i] > peak_val:
                peak_val = mags[i]
                peak_idx = i

        if peak_val < 10.0:
            return 0.0

        # Parabolic interpolation for sub-bin frequency accuracy
        if 1 < peak_idx < len(mags) - 1:
            alpha = mags[peak_idx - 1]
            beta = mags[peak_idx]
            gamma = mags[peak_idx + 1]
            denom = alpha - 2.0 * beta + gamma
            if abs(denom) > 1e-6:
                p = 0.5 * (alpha - gamma) / denom
                peak_idx = peak_idx + p

        freq = peak_idx * float(self._sample_rate) / float(n_fft)
        return round(freq, 1)

    @property
    def note(self):
        """Return the musical note name corresponding to ``peak_freq`` (e.g. 'A4')."""
        return freq_to_note(self.peak_freq)

    def spectrum(self, bins=16, normalize=True):
        """
        Capture a frame and return ``bins`` frequency band levels (0.0 .. 1.0).
        Can be passed directly to ``oled.show_spectrum(mic.spectrum())``.
        """
        pcm = self.read_pcm()
        return spectrum(pcm, bins=bins, normalize=normalize)

    def mfcc(self, num_cepstra=13, num_filters=26):
        """
        Capture a frame and return ``num_cepstra`` MFCC coefficients for TinyML audio classification.
        """
        pcm = self.read_pcm()
        return mfcc(pcm, sample_rate=self._sample_rate,
                    num_cepstra=num_cepstra, num_filters=num_filters)

    def record(self, duration=1.0):
        """
        Record PCM audio for ``duration`` seconds into memory (leveraging ESP32-S3 PSRAM).
        Returns an ``array('h')`` of 16-bit signed PCM samples.
        """
        total_samples = max(1, int(float(duration) * self._sample_rate))
        return self.read_pcm(samples=total_samples)

    def save_wav(self, filename, duration=1.0, pcm_data=None):
        """
        Record audio for ``duration`` seconds (or use pre-recorded ``pcm_data``)
        and save it as a standard 16-bit Mono WAV file.
        """
        if pcm_data is None:
            pcm_data = self.record(duration=duration)

        header = build_wav_header(
            sample_rate=self._sample_rate,
            bits_per_sample=16,
            channels=1,
            num_samples=len(pcm_data),
        )
        with open(filename, "wb") as f:
            f.write(header)
            f.write(struct.pack("<{}h".format(len(pcm_data)), *pcm_data))

        _hal.record_event("i2s_mic", self._pin_nums[0], "save_wav", filename)
        return filename

    # ── Event Callbacks (when_loud, when_quiet, when_clap) ─────────

    def _update_polling(self):
        need_poll = any((self._when_loud, self._when_quiet, self._when_clap))
        if need_poll and not self._polling:
            self._polling = True
            self._poll_timer.init(period=30, callback=self._poll_step)
        elif not need_poll and self._polling:
            self._polling = False
            self._poll_timer.deinit()

    def _poll_step(self, _=None):
        if not self._polling:
            return
        try:
            lvl = self.level
            now = ticks_ms()

            # Loud / Quiet state transitions
            if not self._is_loud_state and lvl >= self._threshold:
                self._is_loud_state = True
                if self._when_loud:
                    self._when_loud()
            elif self._is_loud_state and lvl < (self._threshold * 0.75):
                self._is_loud_state = False
                if self._when_quiet:
                    self._when_quiet()

            # Clap / impulse detection (sharp transient spike that decays quickly)
            if self._when_clap:
                if lvl >= self._clap_threshold:
                    if self._spike_start_ms is None:
                        self._spike_start_ms = now
                else:
                    if self._spike_start_ms is not None:
                        spike_dur = ticks_diff(now, self._spike_start_ms)
                        since_last = ticks_diff(now, self._last_clap_ms)
                        self._spike_start_ms = None
                        if 5 <= spike_dur <= 250 and since_last >= 250:
                            self._last_clap_ms = now
                            self._when_clap()
        except Exception as e:
            print("[espzero] I2SMic callback error:", e)
        finally:
            if self._polling:
                self._poll_timer.init(period=30, callback=self._poll_step)

    @property
    def when_loud(self):
        return self._when_loud

    @when_loud.setter
    def when_loud(self, cb):
        self._when_loud = cb
        self._update_polling()

    @property
    def when_quiet(self):
        return self._when_quiet

    @when_quiet.setter
    def when_quiet(self, cb):
        self._when_quiet = cb
        self._update_polling()

    @property
    def when_clap(self):
        return self._when_clap

    @when_clap.setter
    def when_clap(self, cb):
        self._when_clap = cb
        self._update_polling()

    def close(self):
        """Stop background monitoring and release the hardware I2S peripheral."""
        self._polling = False
        self._poll_timer.deinit()
        if self._i2s is not None:
            try:
                self._i2s.deinit()
            except Exception:
                pass
            self._i2s = None


class I2SSpeaker(PinsMixin):
    """
    I2S Digital Audio Amplifier / Speaker controller (MAX98357A, PCM5102A, etc.).

    Uses hardware ``I2S(1)`` in TX mode by default so it runs alongside
    ``I2SMic`` (``I2S(0)`` RX) and the OV2640 camera without pin or bus conflicts.

    Quick start::

        from espzero import I2SSpeaker

        spk = I2SSpeaker(sample_rate=24000)   # ESP32-S3 defaults: BCLK=38, LRC=39, DIN=40
        spk.play_pcm(pcm_bytes)
        spk.play_wav("hello.wav")
        spk.close()
    """

    def __init__(self, sck="i2s_spk_sck", ws="i2s_spk_ws", sd="i2s_spk_sd",
                 i2s_id=1, sample_rate=24000, bits=16, ibuf=16384):
        if _hal.I2S is None:
            raise RuntimeError("[espzero] machine.I2S is not available on this board.")

        p = _hal.get_profile()
        sck_gpio = I2SMic._resolve_or_fallback(p, sck, 38 if p.CHIP == "esp32s3" else 26)
        ws_gpio  = I2SMic._resolve_or_fallback(p, ws,  39 if p.CHIP == "esp32s3" else 25)
        sd_gpio  = I2SMic._resolve_or_fallback(p, sd,  40 if p.CHIP == "esp32s3" else 22)

        self._pin_nums = (sck_gpio, ws_gpio, sd_gpio)
        self._i2s_id = i2s_id
        self._sample_rate = int(sample_rate)
        self._bits = int(bits)

        self._i2s = _hal.I2S(
            i2s_id,
            sck=Pin(sck_gpio),
            ws=Pin(ws_gpio),
            sd=Pin(sd_gpio),
            mode=_hal.I2S.TX,
            bits=self._bits,
            format=_hal.I2S.MONO,
            rate=self._sample_rate,
            ibuf=ibuf,
        )

    @property
    def sample_rate(self):
        return self._sample_rate

    def play_pcm(self, pcm_data):
        """
        Write raw 16-bit signed little-endian PCM bytes/memoryview/array directly
        to the I2S amplifier.
        """
        if self._i2s is None or not pcm_data:
            return 0
        if isinstance(pcm_data, array):
            pcm_data = struct.pack("<{}h".format(len(pcm_data)), *pcm_data)
        written = self._i2s.write(pcm_data)
        _hal.record_event("i2s_speaker", self._pin_nums[0], "play_pcm", len(pcm_data))
        return written

    write = play_pcm

    def play_wav(self, source, chunk_size=4096):
        """
        Play a 16-bit mono WAV file path (``str``) or in-memory WAV bytes,
        automatically skipping the standard 44-byte RIFF/WAVE header.
        """
        if isinstance(source, str):
            with open(source, "rb") as f:
                head = f.read(44)
                if head and not head.startswith(b"RIFF"):
                    self.play_pcm(head)
                buf = bytearray(chunk_size)
                while True:
                    n = f.readinto(buf)
                    if not n:
                        break
                    self.play_pcm(memoryview(buf)[:n])
            return

        if source:
            mv = memoryview(source)
            if len(mv) > 44 and bytes(mv[:4]) == b"RIFF":
                mv = mv[44:]
            self.play_pcm(mv)

    def close(self):
        """Release the hardware I2S TX peripheral."""
        if self._i2s is not None:
            try:
                self._i2s.deinit()
            except Exception:
                pass
            self._i2s = None


