def get_ai_result():
    """
    Returns the latest audio AI classification result received from PC/Web:
    ``{'label': str | None, 'score': float, 'action': str | None}``
    """
    return _latest_audio_ai


def _url_decode(s):
    return s.replace("%20", " ").replace("+", " ")


def _audio_wifi_server_loop(mic, port, chunk_samples):
    """
    Internal HTTP streaming server loop over Wi-Fi.
    - ``GET /``       : Streams continuous 16-bit mono WAV PCM audio.
    - ``GET /ai?...`` : Receives audio AI classification results (e.g. ``?label=clap&score=0.95&action=GO``).
    """
    global _audio_streaming_active, _latest_audio_ai
    import socket

    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        s.bind(("0.0.0.0", port))
        s.listen(2)
        s.settimeout(1.0)
    except Exception as e:
        print("[Audio] Socket bind error:", e)
        return

    # Infinite/streaming WAV header (data_size = 0xFFFFFFFF) when a hardware mic is attached
    wav_stream_header = (
        build_wav_header(
            sample_rate=mic.sample_rate,
            bits_per_sample=16,
            channels=1,
            num_samples=0x3FFFFFFF,
        )
        if mic is not None
        else None
    )

    while _audio_streaming_active:
        try:
            client, addr = s.accept()
        except OSError:
            continue
        except Exception:
            break

        try:
            client.settimeout(2.0)
            req = client.recv(1024)
            if not req:
                client.close()
                continue

            req_str = req.decode("latin1", "ignore")

            # Handle AI classification feedback endpoint: GET /ai?label=yes&score=0.92&action=GO
            if "/ai" in req_str:
                try:
                    q_idx = req_str.find("?")
                    if q_idx != -1:
                        params = req_str[q_idx + 1 :].split(" ")[0].split("&")
                        p_dict = {}
                        for p in params:
                            if "=" in p:
                                k, v = p.split("=", 1)
                                p_dict[k] = _url_decode(v)

                        label = p_dict.get("label", p_dict.get("cmd", None))
                        action = p_dict.get("action", label)
                        try:
                            score = float(p_dict.get("score", 1.0))
                        except Exception:
                            score = 1.0

                        ai_dict = dict(p_dict)
                        ai_dict.update({
                            "label": label,
                            "score": score,
                            "action": action,
                        })
                        _latest_audio_ai = ai_dict

                        # Also inject into __main__ for seamless access like vision.py
                        try:
                            import __main__
                            setattr(__main__, "__pc_audio_ai", ai_dict)
                        except Exception:
                            pass
                except Exception:
                    pass

                client.sendall(
                    b"HTTP/1.1 200 OK\r\n"
                    b"Content-Type: text/plain\r\n"
                    b"Access-Control-Allow-Origin: *\r\n\r\nOK"
                )
                client.close()
                continue

            if mic is None:
                client.sendall(
                    b"HTTP/1.1 200 OK\r\n"
                    b"Content-Type: text/plain\r\n"
                    b"Connection: close\r\n\r\nespzero audio AI receiver active"
                )
                client.close()
                continue

            # Standard continuous WAV PCM audio stream endpoint
            client.sendall(
                b"HTTP/1.1 200 OK\r\n"
                b"Connection: close\r\n"
                b"Server: espzero-audio\r\n"
                b"Content-Type: audio/wav\r\n"
                b"Cache-Control: no-cache\r\n"
                b"Access-Control-Allow-Origin: *\r\n\r\n"
                + wav_stream_header
            )

            client.settimeout(1.0)
            while _audio_streaming_active:
                pcm = mic.read_pcm(samples=chunk_samples)
                raw = struct.pack("<{}h".format(len(pcm)), *pcm)
                client.sendall(raw)

        except Exception:
            pass
        finally:
            try:
                client.close()
            except Exception:
                pass

    try:
        s.close()
    except Exception:
        pass


def start_wifi_stream(mic=None, port=8081, background=True, chunk_samples=512, sample_rate=16000):
    """
    Streams live 16-bit mono WAV PCM audio from an ``I2SMic`` over Wi-Fi HTTP,
    and exposes a ``/ai`` endpoint to receive real-time audio AI classification
    results (e.g. from Whisper, Edge Impulse, or SpeechRecognition on PC).

    :param mic: An existing ``I2SMic`` instance. If None, creates one with default pins.
    :param port: HTTP server port (default: 8081, avoiding conflict with vision's 8080).
    :param background: Run the HTTP server in a background thread (default: True).
    :param chunk_samples: PCM samples sent per chunk (default: 512).
    :param sample_rate: Sample rate used if creating a new ``I2SMic`` (default: 16000).
    """
    global _audio_streaming_active, _audio_stream_thread

    if _audio_streaming_active:
        print("[Audio] WiFi audio stream is already running.")
        return

    # Determine Wi-Fi IP address
    ip = None
    try:
        import network
        sta = network.WLAN(network.STA_IF)
        if sta.isconnected():
            ip = sta.ifconfig()[0]
        else:
            ap = network.WLAN(network.AP_IF)
            if ap.active():
                ip = ap.ifconfig()[0]
    except Exception:
        pass

    if not ip or ip == "0.0.0.0":
        if _hal._IS_MICROPYTHON:
            print("[Audio] Error: WiFi is not connected. Connect using WiFi().connect('SSID', 'password') first.")
            return
        ip = "127.0.0.1"

    if mic is None:
        mic = I2SMic(sample_rate=sample_rate)

    print("[Audio] Starting WiFi audio stream at http://{}:{}/ ({} Hz)...".format(ip, port, mic.sample_rate))
    _audio_streaming_active = True

    if background and _thread is not None:
        try:
            if _hal._IS_MICROPYTHON and hasattr(_thread, "stack_size"):
                _thread.stack_size(8192)
            _audio_stream_thread = _thread.start_new_thread(
                _audio_wifi_server_loop, (mic, port, chunk_samples)
            )
            return
        except Exception as e:
            print("[Audio] Background WiFi thread start failed ({}), falling back to blocking mode.".format(e))

    try:
        _audio_wifi_server_loop(mic, port, chunk_samples)
    except KeyboardInterrupt:
        print("\n[Audio] Stream stopped by user.")
    finally:
        _audio_streaming_active = False


def start_ai_receiver(port=8081, background=True):
    """
    Starts a lightweight Wi-Fi HTTP receiver on *port* (default: 8081) that accepts
    ``GET /ai?action=...&label=...&score=...`` from a PC script without requiring an
    ``I2SMic`` hardware microphone. Results are read via ``audio.get_ai_result()``.
    """
    global _audio_streaming_active, _audio_stream_thread

    if _audio_streaming_active:
        print("[Audio] WiFi audio server is already running.")
        return

    _audio_streaming_active = True
    if background and _thread is not None:
        try:
            if _hal._IS_MICROPYTHON and hasattr(_thread, "stack_size"):
                _thread.stack_size(8192)
            _audio_stream_thread = _thread.start_new_thread(
                _audio_wifi_server_loop, (None, port, 0)
            )
            return
        except Exception as e:
            print("[Audio] Background receiver thread start failed ({}), falling back to blocking mode.".format(e))

    try:
        _audio_wifi_server_loop(None, port, 0)
    except KeyboardInterrupt:
        print("\n[Audio] Receiver stopped by user.")
    finally:
        _audio_streaming_active = False


def stop_stream():
    """Stops the background Wi-Fi audio streaming loop."""
    global _audio_streaming_active
    _audio_streaming_active = False
    sleep(0.2)

